const weekViewSelectedLabel = computed(() => {
  if (weekViewTeacherIds.value.length === 0) return '全部老師';
  const names = weekViewTeacherIds.value
    .map(id => visibleTeachers.value.find(t => String(t.id) === String(id))?.username)
